    actor,
    pr_number: number,
    task_id: (String(snapshot?.title || pr?.title || '').match(/\bGA-\d{2}\b/) || [null])[0],
    head_sha: head || null,
    review_status: 'UNKNOWN',
    severity: 'INFO',
