  if (event.kind !== 'CODEX_COMMENT_UNCORRELATED' && event.kind !== 'CODEX_STATUS_UNKNOWN' && !event.head_sha) return null;
  event.route = ['P0', 'P1', 'NORMAL'].includes(event.severity) ? 'immediate' : 'digest';
